def gen(rng):
    def build(vals, mode):
        # vals sorted distinct; node id = rank. returns (L, R, root)
        n = len(vals)
        L = [-1] * n
        R = [-1] * n
        stack = [(0, n, -1, 0, 0)]
        root = -1
        while stack:
            lo, hi, par, side, depth = stack.pop()
            if lo >= hi:
                continue
            if mode == 'rand':
                k = rng.randint(lo, hi - 1)
            elif mode == 'left':
                k = hi - 1
            elif mode == 'right':
                k = lo
            else:
                k = hi - 1 if depth % 2 == 0 else lo
            if par == -1:
                root = k
            elif side == 0:
                L[par] = k
            else:
                R[par] = k
            stack.append((lo, k, k, 0, depth + 1))
            stack.append((k + 1, hi, k, 1, depth + 1))
        return L, R, root

    def serialize(vals, L, R, root):
        out = []
        q = [root]
        h = 0
        while h < len(q):
            u = q[h]
            h += 1
            if u == -1:
                out.append('null')
            else:
                out.append(str(vals[u]))
                q.append(L[u])
                q.append(R[u])
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def make(n, mode, hi=10**9, adjacent=None, force=None):
        vs = sorted(rng.sample(range(-hi, hi + 1), n))
        L, R, root = build(vs, mode)
        if force is not None:
            a, b = force
        elif adjacent is True:
            a = rng.randrange(n - 1)
            b = a + 1
        else:
            a, b = rng.sample(range(n), 2)
        vs[a], vs[b] = vs[b], vs[a]
        return serialize(vs, L, R, root)

    tests = [make(2, 'rand'), make(2, 'left'), make(2, 'right'), make(3, 'rand'), make(3, 'rand'), make(3, 'left', force=(0, 2)),
             "5 3 8 2 6 7 9", "2 3 null 1"]
    for n in range(3, 16):
        for mode in ('rand', 'rand', 'left', 'right', 'zig'):
            tests.append(make(n, mode, hi=50 if n < 30 else 10**9))
        tests.append(make(n, 'rand', adjacent=True))
    N = 10**5
    tests.append(make(N, 'rand'))
    tests.append(make(N, 'rand', adjacent=True))
    tests.append(make(N, 'rand', force=(0, N - 1)))
    tests.append(make(5000, 'left'))
    tests.append(make(5000, 'zig'))
    tests.append(make(5000, 'right', force=(1, 4998)))
    return tests
